using FluentAssertions;
using NexusMods.Games.Bethesda.LoadOrder.Formats;

namespace NexusMods.Games.Bethesda.LoadOrder.Tests.Formats;

public class PluginListFormatTests
{
    private static readonly PluginListEntry[] Entries =
    [
        new("Skyrim.esm", true, IsEarlyLoader: true),
        new("A.esp", true),
        new("B.esp", false),
        new("C.esp", true),
    ];

    [Fact]
    public void AsteriskRendersStarsForActiveAndOmitsEarlyLoaders()
    {
        AsteriskPluginList.Render(Entries, writeEarlyLoaders: false).Should().Be(
            "# Generated by SilverModManager\n*A.esp\nB.esp\n*C.esp\n");
    }

    [Fact]
    public void AsteriskCanWriteEarlyLoaders()
    {
        AsteriskPluginList.Render(Entries, writeEarlyLoaders: true).Should().Be(
            "# Generated by SilverModManager\n*Skyrim.esm\n*A.esp\nB.esp\n*C.esp\n");
    }

    [Fact]
    public void AsteriskWritesAnEarlyLoaderThatAsksToBeRenderedExplicitlyAndStillOmitsTheOthers()
    {
        PluginListEntry[] entries =
        [
            new("Skyrim.esm", true, IsEarlyLoader: true),
            new("ccgame.esm", false, IsEarlyLoader: true, RenderExplicitly: true),
            new("A.esp", true),
        ];

        AsteriskPluginList.Render(entries, writeEarlyLoaders: false).Should().Be(
            "# Generated by SilverModManager\nccgame.esm\n*A.esp\n");
    }

    [Fact]
    public void AsteriskParseReadsAnExplicitUnstarredLineAsAnOrdinaryInactiveEntry()
    {
        var parsed = AsteriskPluginList.Parse("ccgame.esm\n*A.esp\n");

        parsed.Should().Equal(new PluginListEntry("ccgame.esm", false), new PluginListEntry("A.esp", true));
    }

    [Fact]
    public void AsteriskParseSkipsALineThatIsOnlyAStar()
    {
        AsteriskPluginList.Parse("*\n*A.esp\n").Select(e => e.Name).Should().Equal("A.esp");
    }

    [Fact]
    public void AsteriskParseIgnoresCommentsBlankLinesAndCarriageReturns()
    {
        var parsed = AsteriskPluginList.Parse("# Generated by SilverModManager\r\n\r\n*A.esp\r\nB.esp\r\n# note\r\n*C.esp");
        parsed.Select(e => (e.Name, e.Active)).Should().Equal(("A.esp", true), ("B.esp", false), ("C.esp", true));
    }

    [Fact]
    public void AsteriskRoundTrips()
    {
        var parsed = AsteriskPluginList.Parse(AsteriskPluginList.Render(Entries, writeEarlyLoaders: true));
        parsed.Select(e => (e.Name, e.Active)).Should().Equal(Entries.Select(e => (e.Name, e.Active)));
    }

    [Fact]
    public void AsteriskKeepsNamesWithSpacesAndNonAscii()
    {
        var entries = new PluginListEntry[] { new("My Mod é.esp", true), new("Other Mod.esp", false) };
        AsteriskPluginList.Parse(AsteriskPluginList.Render(entries, false)).Select(e => e.Name)
            .Should().Equal("My Mod é.esp", "Other Mod.esp");
    }

    [Fact]
    public void AsteriskOfNothingIsJustTheHeader()
    {
        AsteriskPluginList.Render([], false).Should().Be("# Generated by SilverModManager\n");
        AsteriskPluginList.Parse("").Should().BeEmpty();
    }

    [Fact]
    public void PlainRendersActiveNamesOnly()
    {
        PlainPluginList.Render(Entries).Should().Be("# Generated by SilverModManager\nSkyrim.esm\nA.esp\nC.esp\n");
    }

    [Fact]
    public void PlainParseGivesActiveEntriesAndSkipsCommentsAndBlankLines()
    {
        var parsed = PlainPluginList.Parse("# Generated by SilverModManager\n\nA.esp\r\n\nC.esp\n");
        parsed.Select(e => (e.Name, e.Active)).Should().Equal(("A.esp", true), ("C.esp", true));
    }

    [Fact]
    public void PlainRoundTrips()
    {
        var active = Entries.Where(e => e.Active).ToArray();
        PlainPluginList.Parse(PlainPluginList.Render(active)).Select(e => e.Name).Should().Equal(active.Select(e => e.Name));
    }

    [Fact]
    public void LoadOrderTxtRendersEveryNameOnePerLine()
    {
        LoadOrderTxt.Render(Entries).Should().Be("# Generated by SilverModManager\nSkyrim.esm\nA.esp\nB.esp\nC.esp\n");
    }

    [Fact]
    public void LoadOrderTxtParseReturnsNamesInOrder()
    {
        LoadOrderTxt.Parse("# Generated by SilverModManager\nSkyrim.esm\n\nA.esp\r\nB.esp\n").Should()
            .Equal("Skyrim.esm", "A.esp", "B.esp");
    }

    [Fact]
    public void LoadOrderTxtRoundTrips()
    {
        LoadOrderTxt.Parse(LoadOrderTxt.Render(Entries)).Should().Equal(Entries.Select(e => e.Name));
    }

    [Fact]
    public void EveryActiveNameInPluginsTxtIsInLoadOrderTxt()
    {
        var active = PlainPluginList.Parse(PlainPluginList.Render(Entries)).Select(e => e.Name);
        var order = LoadOrderTxt.Parse(LoadOrderTxt.Render(Entries));

        order.Should().Contain(active);
        order.Should().Contain(Entries.Single(e => !e.Active).Name);
    }
}
